<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, ApiError } from '../api'
import type { Attribute, Idea, Product } from '../types'
import { aiLabels, formatDate, linesToList, listToLines, statusLabels, toast } from '../utils'
import AttributeEditor from '../components/AttributeEditor.vue'
import AttachmentList from '../components/AttachmentList.vue'
import LinkManager from '../components/LinkManager.vue'
import RevisionPanel from '../components/RevisionPanel.vue'
import ConflictDialog from '../components/ConflictDialog.vue'
import { useEvents } from '../events'

const route = useRoute(); const router = useRouter(); const id = route.params.id as string
const idea = ref<Idea>(); const names = ref(''); const types = ref(''); const directions = ref(''); const tags = ref(''); const loading = ref(true); const saving = ref(false); const error = ref(''); const dirty = ref(false); const savedPayload = ref(''); const showHistory = ref(false); const uploadBusy = ref(false); const conflict = ref<{ current: Idea; submitted: Record<string, unknown> } | null>(null); const remoteNotice = ref(false); const showCreateProduct = ref(false); const productBusy = ref(false)
const productForm = ref({ internal_name: '', final_brand_name: '', company: '', category: '', description: '', development_status: 'concept', attributes: [] as Attribute[] })
const payload = computed(() => idea.value ? { version: idea.value.version, content: idea.value.content, display_title: idea.value.display_title, summary: idea.value.summary, notes: idea.value.notes, name_candidates: linesToList(names.value), idea_types: linesToList(types.value), product_directions: linesToList(directions.value), tags: linesToList(tags.value), attributes: idea.value.attributes.map(({ key, value, certainty }) => ({ key, value, certainty })) } : null)
const payloadKey = (value: Record<string, unknown> | null) => JSON.stringify(Object.fromEntries(Object.entries(value || {}).filter(([key]) => key !== 'version')))
watch(payload, value => { dirty.value = payloadKey(value) !== savedPayload.value }, { deep: true })
function apply(value: Idea) { idea.value = value; names.value = listToLines(value.name_candidates); types.value = listToLines(value.idea_types); directions.value = listToLines(value.product_directions); tags.value = listToLines(value.tags); savedPayload.value = payloadKey(payload.value); dirty.value = false; remoteNotice.value = false }
async function load(force = false) { loading.value = true; error.value = ''; try { const latest = await api<Idea>(`/ideas/${id}`); if (idea.value && dirty.value && !force) remoteNotice.value = true; else apply(latest) } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
async function save() { if (!payload.value || saving.value) return; saving.value = true; error.value = ''; try { const updated = await api<Idea>(`/ideas/${id}`, { method: 'PATCH', body: JSON.stringify(payload.value) }); apply(updated); toast('已保存') } catch (e) { if (e instanceof ApiError && e.status === 409 && e.details?.current) conflict.value = { current: e.details.current, submitted: { ...payload.value, ...e.details.submitted } }; else error.value = (e as Error).message } finally { saving.value = false } }
function useServer() { if (conflict.value) apply(conflict.value.current); conflict.value = null }
async function mergeLatest() { if (!idea.value || !conflict.value) return; idea.value.version = conflict.value.current.version; conflict.value = null; await save() }
async function runAI(mode: 'normal' | 'full') { if (dirty.value) { error.value = '请先保存当前修改，再运行整理'; return }; if (mode === 'full' && !confirm('重新生成全部可整理字段会覆盖人工修改过的标题、摘要、标签和属性。原始文字与当前正文不会改变。确认继续？')) return; try { await api(`/ideas/${id}/ai`, { method: 'POST', body: JSON.stringify({ mode }) }); if (idea.value) idea.value.ai_status = 'pending'; toast('已加入整理队列') } catch (e) { error.value = (e as Error).message } }
async function upload(images: File[]) { uploadBusy.value = true; try { for (const file of images) { const form = new FormData(); form.append('idea_id', id); form.append('file', file); const attachment = await api<any>('/attachments', { method: 'POST', body: form }); idea.value?.attachments.push(attachment) }; toast('图片已上传') } catch (e) { error.value = (e as Error).message } finally { uploadBusy.value = false } }
async function deleteAttachment(attachmentID: string) { if (!confirm('删除这张图片？')) return; await api(`/attachments/${attachmentID}`, { method: 'DELETE' }); if (idea.value) idea.value.attachments = idea.value.attachments.filter(item => item.id !== attachmentID) }
async function refreshLinks() { const latest = await api<Idea>(`/ideas/${id}`); if (idea.value && dirty.value) { idea.value.links = latest.links; idea.value.product_count = latest.product_count } else apply(latest) }
async function favorite() { if (!idea.value) return; try { const result = await api<{ favorite: boolean }>(`/ideas/${id}/favorite`, { method: 'POST', body: JSON.stringify({ favorite: !idea.value.favorite }) }); idea.value.favorite = result.favorite } catch (e) { error.value = (e as Error).message } }
async function remove() { if (!idea.value || !confirm('将这条灵感移入回收站？关联的商品不会被删除。')) return; await api(`/ideas/${id}`, { method: 'DELETE', body: JSON.stringify({ version: idea.value.version }) }); toast('已移入回收站'); router.push('/ideas') }
function openCreateProduct() { if (!idea.value) return; productForm.value.internal_name = idea.value.display_title || idea.value.content.slice(0,80); productForm.value.description = idea.value.content; productForm.value.category = ''; productForm.value.final_brand_name = ''; productForm.value.company = ''; productForm.value.attributes = []; showCreateProduct.value = true }
async function createProduct() { productBusy.value = true; try { const product = await api<Product>('/products', { method: 'POST', body: JSON.stringify({ ...productForm.value, idea_id: id }) }); showCreateProduct.value = false; toast('商品已创建并关联，原始灵感保持不变'); router.push(`/products/${product.id}`) } catch (e) { error.value = (e as Error).message } finally { productBusy.value = false } }
onMounted(() => load())
useEvents(() => { if (dirty.value) remoteNotice.value = true; else load() })
</script>
<template><div v-if="loading" class="muted">读取中…</div><p v-else-if="!idea" class="error-text">{{ error }}</p><template v-else><div class="page-heading"><div><RouterLink to="/ideas">← 返回灵感库</RouterLink><h1>{{ idea.display_title || '编辑灵感' }}</h1><p>{{ idea.author_nickname }} 创建于 {{ formatDate(idea.created_at) }} · 版本 {{ idea.version }}</p></div><div class="heading-actions"><button class="secondary" :aria-label="idea.favorite ? '取消收藏' : '收藏'" @click="favorite">{{ idea.favorite ? '★ 已收藏' : '☆ 收藏' }}</button><button class="secondary" @click="showHistory = !showHistory">修改历史</button><button class="danger-button" @click="remove">移入回收站</button></div></div><p v-if="remoteNotice" class="ai-status">服务器上有新变更。保存时如发生冲突，会提供差异供你合并。</p><div class="detail-layout"><div class="detail-main"><section class="panel"><div class="ai-status" :class="{ failed: idea.ai_status === 'failed' }">{{ aiLabels[idea.ai_status] }}<span v-if="idea.ai_error"> · {{ idea.ai_error }}</span><button class="button-link" style="margin-left:.6rem" @click="runAI('normal')">{{ idea.ai_status === 'failed' ? '重试' : '重新整理' }}</button><button v-if="idea.content.trim()" class="button-link" style="margin-left:.6rem" @click="runAI('full')">重新生成全部字段</button></div><div class="field"><label for="title">展示标题</label><input id="title" v-model="idea.display_title" maxlength="160" placeholder="可以留空" /></div><div class="field"><label for="content">当前文字</label><textarea id="content" v-model="idea.content" rows="7" maxlength="200000"></textarea><small>修改文字后不会自动调用 AI，可在保存后手动重新整理。</small></div><div class="field"><label for="summary">摘要</label><textarea id="summary" v-model="idea.summary" rows="3" maxlength="4000"></textarea></div><div class="field"><label for="notes">补充备注</label><textarea id="notes" v-model="idea.notes" rows="3" maxlength="20000" placeholder="只记录额外说明，不参与自动整理"></textarea></div><div class="field"><label for="names">名称候选（每行一个）</label><textarea id="names" v-model="names" rows="2"></textarea></div><div class="field-inline"><div class="field"><label for="types">灵感类型</label><input id="types" v-model="types" placeholder="名称、玩法、包装" /><small>用逗号或换行分隔，可多选。</small></div><div class="field"><label for="directions">商品方向</label><input id="directions" v-model="directions" placeholder="饮料、零食" /><small>没有方向可以留空。</small></div></div><div class="field"><label for="tags">标签</label><input id="tags" v-model="tags" placeholder="用逗号或换行分隔" /></div><div class="field"><span class="field-label">动态属性</span><AttributeEditor v-model="idea.attributes" /></div><p v-if="error" class="error-text">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="saving || !dirty" @click="save">{{ saving ? '保存中…' : dirty ? '保存修改' : '已保存' }}</button><span v-if="dirty" class="muted">有未保存修改</span><button class="secondary push-right" @click="openCreateProduct">由此灵感创建商品</button></div></section><section class="panel"><h2>附件</h2><AttachmentList :items="idea.attachments" :busy="uploadBusy" @upload="upload" @delete="deleteAttachment" /></section><details class="panel"><summary>首次提交的原始内容（永久保留）</summary><p class="original-content" style="margin-top:1rem">{{ idea.original_content || '（纯图片投稿，无文字）' }}</p></details><RevisionPanel v-if="showHistory" kind="idea" :id="id" :version="idea.version" @restored="load(true)" /></div><aside class="side-panel"><section class="panel"><h2>关联商品</h2><LinkManager owner-type="idea" :owner-id="id" :links="idea.links || []" @changed="refreshLinks" /></section></aside></div></template>
  <ConflictDialog v-if="conflict" :current="conflict.current" :submitted="conflict.submitted" @server="useServer" @merge="mergeLatest" @cancel="conflict = null" />
  <div v-if="showCreateProduct" class="modal-backdrop"><form class="modal" @submit.prevent="createProduct"><h2>由此灵感创建商品</h2><p class="muted">内部名称只是工作名称。未确定的品牌与暂定属性不会被自动转为正式设定。</p><div class="field"><label for="idea-product-name">内部工作名称</label><input id="idea-product-name" v-model="productForm.internal_name" required maxlength="160" /></div><div class="field"><label>最终品牌名（可留空）</label><input v-model="productForm.final_brand_name" maxlength="160" /></div><div class="field"><label>所属公司（可留空）</label><input v-model="productForm.company" maxlength="160" /></div><div class="field"><label>商品分类（可留空）</label><input v-model="productForm.category" maxlength="100" /></div><div class="field"><label>当前描述</label><textarea v-model="productForm.description" rows="5"></textarea></div><div class="field"><label>制作状态</label><select v-model="productForm.development_status"><option v-for="key in ['concept','design','production','completed']" :key="key" :value="key">{{ statusLabels[key] }}</option></select></div><div class="modal-actions"><button type="button" class="secondary" @click="showCreateProduct = false">取消</button><button class="primary" :disabled="productBusy">创建并关联</button></div></form></div>
</template>
